/*★夜航船★ 作者：不须归*/
/*★献给每一颗美丽的星星，献给我，也献给你，亲爱的★*/
/*★祝你今夜好睡★*/

/* ===== 全局基础设置 ===== */
/* 字体导入与设置 */
@import url("https://fontsapi.zeoseven.com/482/main/result.css");

@font-face {
    font-family: "ZSFT-aq";
    src: url("https://fontsapi.zeoseven.com/aq/main.woff2") format("woff2"),
         url("https://fontsapi-storage.zeoseven.com/aq/main.woff2") format("woff2");
    font-display: swap;
}

body, .mes_text, .text_pole, button, select, input, textarea {
    font-family: "ZSFT-aq", "CooperZhengKai", sans-serif;
    font-weight: normal;
}

/* 滚动条隐藏 */
::-webkit-scrollbar,
::-webkit-scrollbar-track,
::-webkit-scrollbar-thumb {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
}
::-webkit-scrollbar {
    width: 0px !important;
    height: 0px !important;
}
* {
  scrollbar-width: none;
}

/* 底栏QR按键隐藏 */
#send_form:hover #qr--bar {    
  height: 40px;    
  transition: all 0.5s ease;
}
#qr--bar {    
  height: 0.1px;
}

/* ===== 顶部区域组件 ===== */
/* 顶部设置图标 */
#top-settings-holder .drawer-icon::before {
  color: transparent !important;
}
#top-settings-holder .drawer-icon {
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  width: 32px;
  height: 32px;
}
#ai-config-button .drawer-icon { background-image: url('https://i.postimg.cc/fTZHpc9V/retouch-2025081108362534.png'); }
#sys-settings-button .drawer-icon { background-image: url('https://i.postimg.cc/pX2ZqPw8/retouch-2025081108351346.png'); }
#advanced-formatting-button .drawer-icon { background-image: url('https://i.postimg.cc/hG7bfvmF/retouch-2025081108361451.png'); }
#WI-SP-button .drawer-icon { background-image: url('https://i.postimg.cc/jdr9KVGd/retouch-2025081108352559.png'); }
#user-settings-button .drawer-icon { background-image: url('https://i.postimg.cc/MKK71dBm/retouch-2025081108350370.png'); }
#logo_block .drawer-icon { background-image: url('https://i.postimg.cc/QNS5N1z9/retouch-2025081108345357.png'); }
#extensions-settings-button .drawer-icon { background-image: url('https://i.postimg.cc/L5STdShc/retouch-2025081108370402.png'); }
#persona-management-button .drawer-icon { background-image: url('https://i.postimg.cc/fLccfP5B/retouch-2025081108365029.png'); }
#rightNavHolder .drawer-icon { background-image: url('https://i.postimg.cc/fyW9jRVR/retouch-2025081108404630.png'); }

#table_database_settings_drawer .drawer-icon { background-image: url('https://i.postimg.cc/cJwwP8QP/retouch-2025081108353626.png'); }
/* ===== 输入区域组件 ===== */
/* 输入按钮通用样式 */
#leftSendForm > div,
#rightSendForm > div {
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
}
#leftSendForm > div::before,
#rightSendForm > div::before,
#mes_stop i::before {
  content: '' !important;
  font-size: 0 !important;
}
button#cirp-emoji-button-v1 {
  background: none !important;
  border: none !important;
}
button#cirp-emoji-button-v1 > i.fas.fa-smile {
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  width: 28px;
  height: 28px;
}
button#cirp-emoji-button-v1 > i.fas.fa-smile::before {
  content: '' !important;
}

/* 具体按钮样式 */
#options_button { background-image: url('https://i.postimg.cc/C17Z1pcT/retouch-2025081108433406.png'); }
#extensionsMenuButton { background-image: url('https://i.postimg.cc/rwRt9bwx/retouch-2025081108353626.png'); }
#send_but { background-image: url('https://i.postimg.cc/Vk2XQwVK/retouch-2025081108355246.png'); }
#mes_stop { background-image: url('https://i.postimg.cc/fTZHpc9V/retouch-2025081108362534.png'); }
#mes_stop i { color: transparent !important; }
button#cirp-emoji-button-v1 > i.fas.fa-smile { background-image: url('https://i.postimg.cc/pX2ZqPw8/retouch-2025081108351346.png'); }

/* ===== 消息区域组件 ===== */
/* 消息气泡整体布局 */
.mes {
  padding-top: 100px !important;
  margin-top: 20px;
  position: relative !important;
}
.mes::before {
  content: '';
  background-image: url('https://i.postimg.cc/x81N6SLQ/retouch-2025081213423565.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  width: 140px;
  height: 140px;
  position: absolute;
  top: 10px; 
  left: 50%;
  transform: translateX(-50%);
  pointer-events: none;
  z-index: 5;
}

/* 头像区域布局 */
.mes .mesAvatarWrapper {
  position: absolute !important;
  top: 0px !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: auto;
  z-index: 10;
}
.mes .avatar {
  margin-bottom: 5px;
}
.mes .avatar img {
  box-shadow: 0 0 15px rgba(255, 223, 150, 0.6), 0 0 5px rgba(255, 255, 255, 0.8);
}
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
  text-align: center;
  font-size: 0.8em;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.2;
}
.mes .mes_block {
  margin-left: 0 !important;
}

/* 消息气泡样式 */
#chat {
  background-color: transparent !important;
}
@keyframes border-glow {
  0% { box-shadow: inset 0 0 10px rgba(255, 255, 255, 0.2), 0 0 10px rgba(255, 255, 255, 0.2); }
  50% { box-shadow: inset 0 0 15px rgba(255, 255, 255, 0.4), 0 0 15px rgba(255, 255, 255, 0.4); }
  100% { box-shadow: inset 0 0 10px rgba(255, 255, 255, 0.2), 0 0 10px rgba(255, 255, 255, 0.2); }
}
.mes .mes_text {
  background-color: rgba(10, 10, 20, 0.8);
  border-width: 6px;
  border-style: solid;
  padding: 15px 20px !important;
  animation: border-glow 4s ease-in-out infinite;
  transition: all 0.3s ease;
}
.mes .mes_text:hover {
  box-shadow: inset 0 0 20px rgba(255, 255, 255, 0.4), 0 0 20px rgba(255, 255, 255, 0.4);
}
.mes .mes_block::before {
  display: none !important;
}

/* 消息操作按钮 */
.mes_edit::before {
  content: '' !important;
}
.mes_edit {
  background-image: url('https://i.postimg.cc/bNPxSk7H/retouch-2025081304552565.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  width: 24px;
  height: 24px;
}
.extraMesButtonsHint::before {
  content: '' !important;
}
.extraMesButtonsHint {
  background-image: url('https://i.postimg.cc/bNPxSk7H/retouch-2025081304552565.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  width: 24px;
  height: 24px;
}

/* 思维链样式 */
.mes_reasoning_summary {
  background: none !important;
  border: none !important;
  padding: 0 !important;
  margin: 5px auto;
  display: inline-block;
}
.mes_reasoning_header {
  background-image: url('https://i.postimg.cc/brnFYWcq/8abe0fcd-4736-4319-b6af-5fa6d394da6d.jpg');
  background-size: cover;
  background-position: center;
  color: white !important;
  text-shadow: 0 0 3px rgba(255, 223, 150, 0.7);
  padding: 6px 15px;
  border-radius: 50px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  cursor: pointer;
  transition: all 0.2s ease-in-out;
}
.mes_reasoning_header:hover {
  box-shadow: 0 0 10px rgba(255, 223, 150, 0.5);
  border-color: rgba(255, 255, 255, 0.8);
}
.mes_reasoning_arrow {
  color: white !important;
}
.mes_reasoning_header_title {
  font-size: 0 !important;
  color: transparent;
}
.mes_reasoning_header_title::after {
  content: "命运的星辰祝福你"; 
  font-size: 0.8rem;
  color: white;
}

/* ===== 通用UI组件 ===== */
/* 复选框样式 */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-radius: 5px;
  background-color: rgba(0, 0, 0, 0.2);
  vertical-align: middle;
  position: relative;
  top: -2px;
  cursor: pointer;
  transition: all 0.2s ease-in-out;
}
input[type="checkbox"]:hover {
  border-color: rgba(255, 255, 255, 0.8);
  background-color: rgba(0, 0, 0, 0.4);
}
input[type="checkbox"]:checked {
  background-image: url('https://i.postimg.cc/3rFDDmGK/retouch-2025081111062729.png');
  background-size: 90%;
  background-position: center;
  background-repeat: no-repeat;
  border-color: rgba(201, 184, 144, 0.6);
  box-shadow: 0 0 5px rgba(201, 184, 144, 0.5);
}
input[type="checkbox"]::before {
  display: none !important;
}

/* 滑块样式 */
input[type="range"] {
  height: 5px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 5px;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 30px; 
  height: 30px;
  background-image: url('https://i.postimg.cc/8CXCGrMV/retouch-2025081208022723.png');
  background-size: contain; 
  background-position: center;
  background-repeat: no-repeat;
  background-color: transparent;
  border: none;
  cursor: pointer;
  margin-top: -12px; 
}
input[type="range"]::-moz-range-thumb {
  width: 30px;
  height: 30px;
  background-image: url('https://i.postimg.cc/8CXCGrMV/retouch-2025081208022723.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  background-color: transparent;
  border: none;
  cursor: pointer;
}

/* 下拉框样式 */
select.text_pole {
  background-image: url('https://i.postimg.cc/nV7mkNQG/f3eadd4c-3a4f-46be-8013-0703cdb8ca16-edit-193554753887536.jpg');
  background-size: cover;
  background-position: center;
  color: #ffffff !important; 
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 8px;
  box-shadow: 0 0 5px rgba(255, 255, 255, 0.2);
  padding: 5px 8px;
}

/* 标题样式 */
.standoutHeader {
  background-image: url('https://i.postimg.cc/G2Whywzz/planet-edit-199055915080864.jpg');
  background-size: cover;
  background-position: center;
  color: white !important;
  text-shadow: 1px 1px 2px black;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  margin-bottom: 5px; 
}

/* 旋钮图标 */
.inline-drawer-icon {
  position: relative;
  border: none !important;
  border-radius: 0 !important;
  width: 26px !important;
  height: 26px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-shadow: none !important;
  background-color: transparent !important;
  transition: transform 0.3s ease;
}
.inline-drawer-icon::after {
  content: "" !important;
  display: block !important;
  width: 24px;
  height: 24px;
  background-image: url('https://i.postimg.cc/056xmqFc/retouch-2025081111431238.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  transform: rotate(0deg);
  transition: transform 0.3s ease;
}
.inline-drawer-icon::before {
  content: "" !important;
  display: none !important;
}
.inline-drawer-icon.down::after {
  transform: rotate(0deg) !important;
}
.inline-drawer-icon.up::after {
  transform: rotate(180deg) !important;
}
.inline-drawer-icon:hover::after {
  transform: scale(1.15) rotate(var(--current-rotation, 0deg)) !important;
  filter: drop-shadow(0 0 4px rgba(255, 182, 193, 0.8));
}
.inline-drawer-toggle:active .inline-drawer-icon::after {
  transform: scale(0.95) rotate(var(--current-rotation, 0deg)) !important;
}
.inline-drawer-icon,
.inline-drawer-icon::after {
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.27, 1.55);
}

/* --- 左右滑动箭头的美化 --- */

/* 通用样式 */
.swipe_left, .swipe_right {
  font-size: 0 !important;
  width: 35px !important;
  height: 35px !important;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  opacity: 0.8;
  transition: all 0.2s ease-in-out;
}

/* 左箭头 */
.swipe_left {
  background-image: url('https://i.postimg.cc/Jz03zz6V/retouch-2025081111431238.png') !important;
}

/* 
  ！！！新的魔法在这里！！！
  右箭头
*/
.swipe_right {
  background-image: url('https://i.postimg.cc/mD0sVmq8/retouch-2025081403210525.png') !important;
  position: relative; /* 准备移动 */
  right: 10px; /* 向左移动10像素 */
}

/* 悬停效果 */
.swipe_left:hover, .swipe_right:hover {
  opacity: 1;
  transform: scale(1.1);
}

/* ===== 特殊区域样式 ===== */
/* 设置面板 */
.drawer-content {
  background-image: url('https://i.postimg.cc/y8kXV0gK/8c11a4b5-5f4e-4704-9838-a59b89652186.jpg');
  background-size: cover;
  background-position: center;
  background-color: #1a1a1a;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

/* 加载动画 */
@keyframes spin-gently {
  from { transform: translate(-50%, -50%) rotate(0deg); }
  to { transform: translate(-50%, -50%) rotate(360deg); }
}
#load-spinner {
  background: url('https://i.postimg.cc/VvSrtLYt/retouch-2025081305532320.png') no-repeat center center !important;
  background-size: contain !important;
  border: none !important;
  width: 200px !important;
  height: 200px !important;
  position: fixed !important;
  top: 50% !important;
  left: 50% !important;
  animation: spin-gently 4s linear infinite !important;
  z-index: 99999;
}
#load-spinner::before,
#load-spinner::after {
  display: none !important;
}

/* === 梦幻星空引用块！ === */

/* 引用块主体样式 */
.mes_text q {
  /* 基础布局 */
  display: inline-block;
  position: relative;
  /* 
    ！！！关键改动在这里！！！
    我们把左内边距从 50px 减小到 25px，让文字更靠左。
  */
  padding: 15px 20px 15px 25px; 
  margin: 10px 0;

  /* 字体与排版 */
  font-family: "CooperZhengKai", serif !important;
  font-size: 1.0em;
  /* ✏️字体大小可调整 */
  font-style: italic;
  line-height: 1.6;
  color: #f0e6ff !important;
  text-shadow: 0 0 5px rgba(200, 180, 255, 0.4);

  /* 星空背景与边框 */
  background: 
    radial-gradient(circle at 30% 40%, rgba(35, 20, 70, 0.8) 0%, rgba(15, 8, 40, 0.9) 100%),
    url('https://i.postimg.cc/6qZWL371/b2e1462d-66df-4041-a339-8b1a030214f4-edit-89393946171558.jpg') !important;
  background-size: cover !important;
  background-blend-mode: soft-light;
  border-left: 3px solid rgba(180, 150, 255, 0.6) !important;
  border-radius: 0 15px 15px 0;
  box-shadow: 
    inset 5px 0 10px rgba(120, 80, 220, 0.3),
    0 0 15px rgba(80, 60, 160, 0.3);

  transition: all 0.4s ease;
}

/* 底部装饰 - 星轨 */
.mes_text q::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, 
    transparent, 
    rgba(180, 150, 255, 0.6), 
    rgba(120, 80, 220, 0.8),
    rgba(180, 150, 255, 0.6),
    transparent);
  border-radius: 0 0 15px 15px;
}


/* 悬停效果 - 如星辰闪耀 */
.mes_text q:hover {
  transform: translateY(-3px);
  box-shadow: 
    inset 5px 0 15px rgba(150, 120, 240, 0.5),
    0 0 25px rgba(100, 80, 200, 0.5);
  background-blend-mode: overlay;
}
.mes_text q:hover::before {
  color: rgba(220, 190, 255, 1);
  text-shadow: 0 0 15px rgba(220, 190, 255, 0.8);
}

/* 多行引用时的段落间距 */
.mes_text q p {
  margin: 10px 0 !important;
}
/* 引用中的强调文字 */
.mes_text q em {
  color: #ffdb7e !important;
  font-style: normal;
  text-shadow: 0 0 8px rgba(255, 219, 126, 0.5);
  font-weight: bold;
}
/* 引用中的链接 */
.mes_text q a {
  color: #6ab0f3 !important;
  text-decoration: none;
  border-bottom: 1px dotted rgba(106, 176, 243, 0.5);
  transition: all 0.3s ease;
}
.mes_text q a:hover {
  color: #a78bfa !important;
  border-bottom: 1px solid rgba(167, 139, 250, 0.8);
  text-shadow: 0 0 10px rgba(167, 139, 250, 0.6);
}
/* 引用中的代码片段 */
.mes_text q code {
  background: rgba(30, 15, 60, 0.7) !important;
  border: 1px solid rgba(150, 120, 220, 0.3) !important;
  padding: 1px 6px !important;
  border-radius: 4px;
  font-family: "ZSFT-aq", monospace !important;
  font-size: 0.9em;
  box-shadow: inset 0 0 5px rgba(100, 80, 180, 0.4);
}

/* === 代码块 - 星空中的知识宝石 === */
pre, code {
  /* 基础设置 */
  font-family: "ZSFT-aq", "CooperZhengKai", monospace !important;
  border-radius: 12px;
  overflow: auto;
  position: relative;
  z-index: 1;

  /* 添加神秘星空背景 */
  background: 
    radial-gradient(circle at 10% 20%, rgba(25, 15, 60, 0.8) 0%, rgba(10, 5, 30, 0.9) 90%),
    url('https://i.postimg.cc/N080BRF5/b2e1462d-66df-4041-a339-8b1a030214f4-edit-89393946171558.jpg') !important;
  background-size: cover !important; /* 关键修复：覆盖整个区域 */
  background-blend-mode: soft-light;
  background-attachment: local; /* 确保滚动时背景跟随 */

  /* 边框与光影效果 */
  border: 1px solid rgba(140, 120, 200, 0.4) !important;
  box-shadow: 
    inset 0 0 15px rgba(100, 80, 180, 0.5),
    0 0 20px rgba(80, 60, 160, 0.4),
    0 0 5px rgba(255, 255, 255, 0.1);

  /* 添加优雅的星轨装饰 */
  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, 
      transparent, 
      rgba(180, 150, 255, 0.6), 
      rgba(120, 80, 220, 0.8),
      rgba(180, 150, 255, 0.6),
      transparent);
    border-radius: 12px 12px 0 0;
    z-index: 2;
  }
}

/* 代码块容器 */
pre {
  padding: 20px !important;
  margin: 15px 0 !important;

  /* 添加悬停放大效果 */
  transition: transform 0.3s ease, box-shadow 0.3s ease;

  &:hover {
    transform: translateY(-3px);
    box-shadow: 
      inset 0 0 20px rgba(120, 100, 220, 0.7),
      0 5px 30px rgba(80, 60, 180, 0.6),
      0 0 10px rgba(255, 255, 255, 0.2) !important;
  }

  /* 右上角语言标签 */
  &::after {
    content: attr(data-language);
    position: absolute;
    top: 8px;
    right: 15px;
    font-size: 0.7em;
    color: rgba(180, 160, 255, 0.8);
    background: rgba(20, 10, 50, 0.6);
    padding: 2px 8px;
    border-radius: 10px;
    border: 1px solid rgba(140, 120, 220, 0.4);
    z-index: 3;
  }
}

/* 内联代码 */
code:not(pre code) {
  padding: 2px 8px !important;
  margin: 0 2px;
  background: rgba(30, 15, 60, 0.7) !important;
  border: 1px solid rgba(150, 120, 220, 0.3) !important;
  border-radius: 6px;
  box-shadow: inset 0 0 5px rgba(100, 80, 180, 0.4);

  /* 添加闪烁效果 */
  animation: code-pulse 4s infinite;
}

@keyframes code-pulse {
  0%, 100% { opacity: 0.9; }
  50% { opacity: 1; box-shadow: inset 0 0 8px rgba(150, 120, 240, 0.6), 0 0 5px rgba(150, 120, 240, 0.3); }
}

/* 代码文字样式 */
pre code {
  color: #e0d6ff !important;
  text-shadow: 0 0 3px rgba(180, 160, 255, 0.4);
  display: block;
  padding: 0 !important;
  background: transparent !important;
  font-size: 0.95em;
  line-height: 1.5;

  /* 添加行号星光效果 */
  .line-number {
    display: inline-block;
    width: 2.5em;
    margin-right: 1em;
    text-align: right;
    color: rgba(160, 140, 220, 0.6);
    text-shadow: 0 0 5px rgba(140, 120, 220, 0.4);
    position: relative;

    &::after {
      content: '';
      position: absolute;
      right: 0;
      top: 0;
      bottom: 0;
      width: 1px;
      background: linear-gradient(to bottom, 
        transparent, 
        rgba(140, 120, 220, 0.4), 
        transparent);
    }
  }
}
